import {OCRReviewEditor} from '../../src/features/ocr-review.ts';import {reviewOCR} from '../../src/domain/ocr.ts';import catalog from '../../src/data/catalog.json';import type {Experiment} from '../../src/domain/types.ts';
export function openWaterReview(){const exp=(catalog.experiments as Experiment[]).find(e=>e.sourceId==='声速的测量（水中）')!;const review=reviewOCR(exp.schema,JSON.stringify({data:{L1:Array.from({length:10},(_,i)=>i)}}));const host=document.querySelector<HTMLElement>('#fixture')!,messages:string[]=[];const editor=new OCRReviewEditor(exp.schema,review,s=>messages.push(s));editor.mount(host);return {snapshot:()=>editor.snapshot(),restore:(s:any)=>editor.restore(s),corrected:()=>editor.corrected(),messages:()=>messages,leave:()=>editor.leave()};}
